def bookingRackPositiveInkInvoice(drawers):
    a=drawers
    out=[]
    end=float('-inf')
    for s,e in sorted(a,key=lambda r:(r[1],r[0])):
        if s>=end:
            out.append(e-s)
            end=e
    return sum(x for x in out if x>0)

